import os, json, time, math, glob, re
import numpy as np

# Paths
SHARED_DIR = 'storage/shared/appxE_contribs'
NOESIS_DIR = 'storage/noesis/nmap'
RESULTS_DIR = os.path.join(NOESIS_DIR, 'results')
RUN_LOG = os.path.join(NOESIS_DIR, 'aggregator_v2_1_run.json')
SUMMARY_V21 = os.path.join(NOESIS_DIR, 'appendix_E_summary_v2_1.json')
SUMMARY_FALLBACK = os.path.join(NOESIS_DIR, 'appendix_E_summary.json')  # update minimally if present

SNAP_CENTERS = 'storage/noesis/latest_centers.txt'
SNAP_RADII   = 'storage/noesis/latest_radii.txt'

# Policy constants
K_GRID = [15, 25, 40, 60]
TOLS = {'tight': 1e-9, 'loose': 1e-8}
TOL_GRID_AUDIT = [0.8e-8, 1e-8, 1.2e-8, 2e-8]
NEAR_ACTIVE_TOL = 1e-8
R_MIN = 1e-6
FINAL_SHRINK = 1e-9

# ------------- Utilities -------------
def load_snapshot():
  c = np.loadtxt(SNAP_CENTERS, dtype=float).reshape(26,2)
  r = np.loadtxt(SNAP_RADII, dtype=float).reshape(26,)
  return c, r

def ensure_dirs():
  os.makedirs(NOESIS_DIR, exist_ok=True)
  os.makedirs(RESULTS_DIR, exist_ok=True)

def read_json(path):
  try:
    with open(path, 'r') as f:
      return json.load(f)
  except Exception:
    return None

def write_json(path, obj):
  os.makedirs(os.path.dirname(path), exist_ok=True)
  with open(path, 'w') as f:
    json.dump(obj, f, indent=2)

def list_json_files():
  if not os.path.isdir(SHARED_DIR):
    return []
  return sorted([os.path.join(SHARED_DIR, f) for f in os.listdir(SHARED_DIR)
                 if f.lower().endswith('.json') and 'template' not in f.lower()])

def boundary_slacks(c, r):
  x, y = c[:,0], c[:,1]
  return {
    'xL': x - r,
    'xR': 1.0 - x - r,
    'yB': y - r,
    'yT': 1.0 - y - r
  }

def boundary_active_set(c, r, tol):
  bs = boundary_slacks(c, r)
  act = []
  for i in range(26):
    for side in ('xL','xR','yB','yT'):
      if bs[side][i] <= tol:
        act.append({'disc': int(i), 'side': side})
  # Deduplicate by smallest slack per side
  seen = set()
  out = []
  for b in act:
    key = (b['disc'], b['side'])
    if key not in seen:
      seen.add(key); out.append(b)
  return out

def is_boundary_disc(c, r, i, tol):
  bs = boundary_slacks(c, r)
  return (bs['xL'][i] <= tol or bs['xR'][i] <= tol or bs['yB'][i] <= tol or bs['yT'][i] <= tol)

def pair_slack(c, r, i, j):
  d = float(np.hypot(c[i,0]-c[j,0], c[i,1]-c[j,1]))
  return d - (r[i] + r[j])

# Segment intersection (strict)
def _orient(ax, ay, bx, by, cx, cy):
  return (bx-ax)*(cy-ay) - (by-ay)*(cx-ax)

def _on_seg(ax, ay, bx, by, px, py, eps=1e-12):
  return (min(ax,bx)-eps <= px <= max(ax,bx)+eps) and (min(ay,by)-eps <= py <= max(ay,by)+eps)

def seg_intersect_strict(a, b, c, d, eps=1e-12):
  ax, ay = a; bx, by = b; cx, cy = c; dx, dy = d
  o1 = _orient(ax,ay,bx,by,cx,cy)
  o2 = _orient(ax,ay,bx,by,dx,dy)
  o3 = _orient(cx,cy,dx,dy,ax,ay)
  o4 = _orient(cx,cy,dx,dy,bx,by)
  # Proper intersection
  if (o1*o2 < -eps) and (o3*o4 < -eps):
    return True
  return False

# ------------- Schema normalization -------------
def normalize_contribution(path, base_cache):
  """
  Returns dict:
    { 'eval_id': int,
      'boundary_2e8': [{'disc':int,'side':str}],  # optional
      'topk_slack': { '1e-9': {K:set((i,j))}, '1e-8': {K:set((i,j))} },
      'topk_kkt': same structure (optional),
      'index_map_to_noesis': list[26] or None,
      'native_crossings': set of frozenset({(i,j),(k,l)}) or empty
    }
  This function is robust to split files (e.g., *_slack_top_k_1e_9.json).
  """
  fn = os.path.basename(path)
  base = fn
  # Derive a stem to group split files by removing known suffixes
  stem = re.sub(r'(_slack_top_k_1e_9|_slack_top_k_1e_8|_crossings)\.json$', '', fn)
  meta = base_cache.get(stem, {
    'eval_id': None,
    'boundary_2e8': None,
    'topk_slack': {'1e-9': {}, '1e-8': {}},
    'topk_kkt': {'1e-9': {}, '1e-8': {}},
    'index_map_to_noesis': None,
    'native_crossings': set()
  })
  data = read_json(path)
  if not isinstance(data, dict):
    base_cache[stem] = meta
    return None

  # eval_id
  if meta['eval_id'] is None and 'eval_id' in data:
    try: meta['eval_id'] = int(data['eval_id'])
    except Exception: pass

  # boundary
  bkey = 'boundary_2e8' if 'boundary_2e8' in data else ('boundary' if 'boundary' in data else None)
  if bkey and meta['boundary_2e8'] is None:
    braw = data.get(bkey, [])
    bnorm = []
    for b in braw:
      try:
        disc = int(b.get('disc', b[0] if isinstance(b, (list,tuple)) else -1))
        side = b.get('side', b[1] if isinstance(b, (list,tuple)) else None)
        if side in ('xL','xR','yB','yT') and 0 <= disc < 26:
          bnorm.append({'disc': disc, 'side': side})
      except Exception:
        continue
    if len(bnorm) > 0:
      meta['boundary_2e8'] = bnorm

  # index map
  if meta['index_map_to_noesis'] is None and 'index_map_to_noesis' in data:
    arr = data.get('index_map_to_noesis', None)
    if isinstance(arr, list) and len(arr) == 26 and all(isinstance(x, int) and 0 <= x < 26 for x in arr):
      # ensure it's a permutation
      if sorted(arr) == list(range(26)):
        meta['index_map_to_noesis'] = arr

  # native crossings
  if 'native_crossings' in data and isinstance(data['native_crossings'], list):
    for it in data['native_crossings']:
      try:
        p1 = tuple(map(int, it.get('pair1', it.get('p1', []))))
        p2 = tuple(map(int, it.get('pair2', it.get('p2', []))))
        if len(p1)==2 and len(p2)==2 and p1!=p2:
          meta['native_crossings'].add(frozenset({tuple(sorted(p1)), tuple(sorted(p2))}))
      except Exception:
        pass

  # Top-K combined format
  if 'topk' in data and isinstance(data['topk'], list):
    for entry in data['topk']:
      try:
        method = entry.get('method', 'slack').lower()
        tol = str(entry.get('tol','')).replace('e-09','1e-9').replace('e-08','1e-8')
        if tol in ('1e-9','1e-8'):
          K = int(entry.get('K', 0))
          pairs = entry.get('pairs', [])
          s = set()
          for p in pairs:
            i, j = int(p[0]), int(p[1])
            if 0 <= i < 26 and 0 <= j < 26 and i != j:
              s.add(tuple(sorted((i,j))))
          bucket = meta['topk_slack'] if method == 'slack' else meta['topk_kkt']
          bucket[tol][K] = s
      except Exception:
        continue

  # Split slack files by name
  if '_slack_top_k_1e_9' in fn or '_slack_top_k_1e_8' in fn:
    tol = '1e-9' if '_slack_top_k_1e_9' in fn else '1e-8'
    # Expect fields: "K": int, "pairs": [...]
    K = data.get('K', None)
    pairs = data.get('pairs', [])
    if isinstance(K, int) and isinstance(pairs, list):
      s = set()
      for p in pairs:
        try:
          i, j = int(p[0]), int(p[1])
          if 0 <= i < 26 and 0 <= j < 26 and i != j:
            s.add(tuple(sorted((i,j))))
        except Exception:
          pass
      meta['topk_slack'][tol][K] = s

  base_cache[stem] = meta
  return meta

# ------------- Gate evaluation -------------
def apply_index_map(pair_set, idx_map):
  if idx_map is None:
    return pair_set
  out = set()
  for (i,j) in pair_set:
    mi, mj = idx_map[i], idx_map[j]
    out.add(tuple(sorted((mi, mj))))
  return out

def dual_tol_intersection(topk_dict_1e9, topk_dict_1e8, k):
  s1 = topk_dict_1e9.get(k, set())
  s2 = topk_dict_1e8.get(k, set())
  return s1 & s2

def gate_results_for_K(c, r, idx_map, boundary_tol, topk_slack, native_crossings):
  """
  Returns dict per K:
    {K: {'gate_v1_SAT': bool,
         'robust_SAT_v2': bool,
         'example': {'pair1': [i,j], 'pair2':[k,l]} or None,
         'both_near_active_at_1e-8': bool,
         'tol_grid_slacks': { 'pair1': [s_...], 'pair2': [s_...] } } }
  """
  # Precompute boundary mask
  bmask = np.array([is_boundary_disc(c, r, i, boundary_tol) for i in range(26)], dtype=bool)
  res = {}
  for K in K_GRID:
    inter = dual_tol_intersection(topk_slack['1e-9'], topk_slack['1e-8'], K)
    inter = apply_index_map(inter, idx_map)
    # Search disjoint crossing pairs among intersection
    pairs = list(inter)
    found = None
    robust = False
    both_near = False
    tol_sl = None
    for a_idx in range(len(pairs)):
      for b_idx in range(a_idx+1, len(pairs)):
        i,j = pairs[a_idx]
        k,l = pairs[b_idx]
        # disjoint
        if len({i,j,k,l}) < 4:
          continue
        # interior at tol=1e-8
        if bmask[i] or bmask[j] or bmask[k] or bmask[l]:
          continue
        # crossing on Noesis geometry (strict)
        if seg_intersect_strict(tuple(c[i]), tuple(c[j]), tuple(c[k]), tuple(c[l])):
          found = ((i,j), (k,l))
          # tol-grid slacks + near-active check
          s1 = pair_slack(c, r, i, j)
          s2 = pair_slack(c, r, k, l)
          tol_sl = {'pair1': [s1 for _ in TOL_GRID_AUDIT],
                    'pair2': [s2 for _ in TOL_GRID_AUDIT]}
          both_near = (s1 <= NEAR_ACTIVE_TOL) and (s2 <= NEAR_ACTIVE_TOL)
          # robust cross-geometry if provided
          nat = frozenset({tuple(sorted((i,j))), tuple(sorted((k,l)))})
          robust = (nat in native_crossings)
          break
      if found:
        break
    res[K] = {
      'gate_v1_SAT': bool(found),
      'robust_SAT_v2': bool(found and robust),
      'example': None if not found else {'pair1': list(found[0]), 'pair2': list(found[1])},
      'both_near_active_at_1e-8': bool(found and both_near),
      'tol_grid_slacks': tol_sl
    }
  return res

def stability_adjacent(sat_by_K):
  # True if SAT holds for ≥2 adjacent K values
  Ks = sorted([k for k,v in sat_by_K.items() if v])
  for a,b in zip(Ks, Ks[1:]):
    if (a,b) in [(15,25),(25,40),(40,60)]:
      return True
  return False

# ------------- Main aggregation -------------
def run_aggregator_v2_1():
  ensure_dirs()
  c, r = load_snapshot()

  files = list_json_files()
  base_cache = {}
  # First pass: normalize and coalesce by stem
  for path in files:
    normalize_contribution(path, base_cache)

  per_file_results = {}
  summary = {
    'schema_version': '1.1',
    'aggregator_version': '2.1',
    'generated_at': time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime()),
    'files_seen': len(files),
    'stems_processed': 0,
    'eligible_entries': 0,
    'entries': []
  }

  for stem, meta in sorted(base_cache.items()):
    eval_id = meta.get('eval_id', None)
    topk_slack = meta.get('topk_slack', {'1e-9':{}, '1e-8':{}})
    # Require some Top-K for both tolerances
    if not isinstance(topk_slack, dict) or '1e-9' not in topk_slack or '1e-8' not in topk_slack:
      continue

    idx_map = meta.get('index_map_to_noesis', None)
    align_conf = 'high' if idx_map is not None else 'low'
    native_crossings = meta.get('native_crossings', set())

    resK = gate_results_for_K(c, r, idx_map, boundary_tol=NEAR_ACTIVE_TOL, topk_slack=topk_slack, native_crossings=native_crossings)
    gate1_by_K = {k: v['gate_v1_SAT'] for k,v in resK.items()}
    robust_by_K = {k: v['robust_SAT_v2'] for k,v in resK.items()}
    both_near_by_K = {k: v['both_near_active_at_1e-8'] for k,v in resK.items()}
    # Determine eligibility
    stable_gate2 = stability_adjacent({k:v for k,v in robust_by_K.items() if v})
    # Choose an example at the strongest K (prefer middle K)
    bestK = None
    for k in [25,40,15,60]:
      if robust_by_K.get(k, False):
        bestK = k; break
    example = resK.get(bestK, {}).get('example', None) if bestK is not None else None
    both_near = resK.get(bestK, {}).get('both_near_active_at_1e-8', False) if bestK is not None else False

    eligible = bool(stable_gate2 and both_near and align_conf == 'high')

    # Assemble result
    result = {
      'stem': stem,
      'eval_id': eval_id,
      'alignment_confidence': align_conf,
      'k_levels': K_GRID,
      'gate_v1_SAT_by_K': gate1_by_K,
      'robust_SAT_v2_by_K': robust_by_K,
      'both_near_active_at_1e-8_by_K': both_near_by_K,
      'stability_adjacent_gate_v2': stable_gate2,
      'example': example,
      'eligible_for_operator': eligible
    }
    per_file_results[stem] = result
    summary['entries'].append(result)
    if eligible: summary['eligible_entries'] += 1
    summary['stems_processed'] += 1

    # Write per-file
    write_json(os.path.join(RESULTS_DIR, f'{stem}_compare_v2_1.json'), result)

  # Write consolidated
  write_json(SUMMARY_V21, summary)

  # Minimal back-compat: annotate legacy summary if present
  if os.path.exists(SUMMARY_FALLBACK):
    try:
      legacy = read_json(SUMMARY_FALLBACK) or {}
      legacy['v2_1_pointer'] = SUMMARY_V21
      legacy['v2_1_generated_at'] = summary['generated_at']
      write_json(SUMMARY_FALLBACK, legacy)
    except Exception:
      pass

  # Log run
  write_json(RUN_LOG, {
    'status': 'ok',
    'schema_version': '1.1',
    'aggregator_version': '2.1',
    'files_seen': len(files),
    'stems_processed': summary['stems_processed'],
    'eligible_entries': summary['eligible_entries'],
    'generated_at': summary['generated_at']
  })

# ------------- construct_packing (return baseline) -------------
def construct_packing():
  # Run aggregator v2.1 analysis (ignore failures but log)
  try:
    run_aggregator_v2_1()
  except Exception as e:
    try:
      write_json(RUN_LOG, {'status': 'error', 'message': str(e), 'time': time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime())})
    except Exception:
      pass
  # Return Noesis snapshot with tiny shrink (analysis-only)
  c, r = load_snapshot()
  r = np.maximum(r - FINAL_SHRINK, R_MIN)
  return c.astype(float), r.astype(float)
